import fs from 'fs';
import path from 'path';
import { log } from '../../core/logger.js';
export function writeAndroidManifest(config, mainDirectory) {
    const permissions = config.permissions;
    const permMap = [
        [permissions.internet, 'android.permission.INTERNET', undefined],
        [permissions.networkState, 'android.permission.ACCESS_NETWORK_STATE', undefined],
        [permissions.wifiState, 'android.permission.ACCESS_WIFI_STATE', undefined],
        [permissions.coarseLocation, 'android.permission.ACCESS_COARSE_LOCATION', undefined],
        [permissions.fineLocation, 'android.permission.ACCESS_FINE_LOCATION', undefined],
        [permissions.camera, 'android.permission.CAMERA', undefined],
        [permissions.recordAudio, 'android.permission.RECORD_AUDIO', undefined],
        [permissions.readExternalStorage, 'android.permission.READ_EXTERNAL_STORAGE', 'android:maxSdkVersion="32"'],
        [permissions.writeExternalStorage, 'android.permission.WRITE_EXTERNAL_STORAGE', 'android:maxSdkVersion="29"'],
        [permissions.readMediaImages, 'android.permission.READ_MEDIA_IMAGES', 'android:minSdkVersion="33"'],
        [permissions.readMediaVideo, 'android.permission.READ_MEDIA_VIDEO', 'android:minSdkVersion="33"'],
        [permissions.readMediaAudio, 'android.permission.READ_MEDIA_AUDIO', 'android:minSdkVersion="33"'],
        [permissions.vibrate, 'android.permission.VIBRATE', undefined],
        [permissions.receiveBootCompleted, 'android.permission.RECEIVE_BOOT_COMPLETED', undefined],
        [permissions.postNotifications, 'android.permission.POST_NOTIFICATIONS', undefined],
        [permissions.bluetooth, 'android.permission.BLUETOOTH', 'android:maxSdkVersion="30"'],
        [permissions.bluetooth, 'android.permission.BLUETOOTH_CONNECT', undefined],
        [permissions.bluetooth, 'android.permission.BLUETOOTH_SCAN', undefined],
        [permissions.nfc, 'android.permission.NFC', undefined],
        [permissions.biometric, 'android.permission.USE_BIOMETRIC', undefined],
        [permissions.fingerprint, 'android.permission.USE_FINGERPRINT', 'android:maxSdkVersion="28"'],
        [permissions.flashlight, 'android.permission.FLASHLIGHT', undefined],
        [permissions.wakeLock, 'android.permission.WAKE_LOCK', undefined],
        [permissions.foregroundService, 'android.permission.FOREGROUND_SERVICE', undefined],
        [permissions.scheduleExactAlarm, 'android.permission.SCHEDULE_EXACT_ALARM', undefined],
    ];
    const permLines = permMap.filter(([enabled]) => enabled).map(([, name, extra]) => `    <uses-permission android:name="${name}"${extra ? ` ${extra}` : ''} />`).join('\n');
    const netSecAttr = config.clearTextDomains?.length || config.allowAllClearText ? `\n        android:networkSecurityConfig="@xml/network_security_config"` : '';
    const xml = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">

${permLines}

    <application
        android:allowBackup="${config.allowBackup}"
        android:hardwareAccelerated="${config.hardwareAccelerated}"
        android:icon="@mipmap/ic_launcher"
        android:roundIcon="@mipmap/ic_launcher"
        android:label="@string/app_name"
        android:supportsRtl="${config.supportsRtl}"
        android:theme="@style/AppTheme"${netSecAttr}>
        <activity
            android:name=".MainActivity"
            android:configChanges="orientation|screenSize|keyboardHidden"
            android:exported="true"
            android:screenOrientation="${config.orientation ?? 'unspecified'}"
            android:windowSoftInputMode="adjustResize">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
    </application>
</manifest>`;
    fs.writeFileSync(path.join(mainDirectory, 'AndroidManifest.xml'), xml);
    log.dim('  AndroidManifest.xml');
}
